function news2ScoreFor(p){var spo2=Number(p.spo2),hr=Number(p.hr),rr=Number(p.rr),temp=Number(p.temp),sbp=parseInt(String(p.bp).split("/")[0],10)||0;var scoreRR=rr<=8?3:rr<=11?1:rr<=20?0:rr<=24?2:3;var scoreSpO2=spo2<=91?3:spo2<=93?2:spo2<=95?1:0;var scoreSBP=sbp<=90?3:sbp<=100?2:sbp<=110?1:sbp<=219?0:3;var scorePulse=hr<=40?3:hr<=50?1:hr<=90?0:hr<=110?1:hr<=130?2:3;var scoreTemp=temp<=35?3:temp<=36?1:temp<=38?0:temp<=39?1:2;var parts=[{label:"呼吸频率 "+rr+"/min",score:scoreRR},{label:"SpO₂ "+spo2+"% · Scale 1",score:scoreSpO2},{label:"脉搏 "+hr+"/min",score:scorePulse},{label:"收缩压 "+sbp+" mmHg",score:scoreSBP},{label:"体温 "+temp+"°C",score:scoreTemp},{label:"意识 Alert · 未用氧",score:0}];return {total:scoreRR+scoreSpO2+scoreSBP+scorePulse+scoreTemp,red:parts.some(function(part){return part.score===3}),parts:parts};}
